<script setup>
import{ref,onMounted}from'vue';import{useI18n}from'vue-i18n';import{api,errorMessage}from'../../../shared/infrastructure/base-api.js';
const{t}=useI18n();const receiveQuantities=ref({});const products=ref([]),orders=ref([]),supplierName=ref(''),productId=ref(''),quantity=ref(1),unitCost=ref(0),error=ref(''),busy=ref(false);
async function load(){[products.value,orders.value]=await Promise.all([api.get('/inventory').then(r=>r.data),api.get('/purchases').then(r=>r.data)]);}
async function submit(){busy.value=true;error.value='';try{await api.post('/purchases',{supplierName:supplierName.value,productId:productId.value,quantity:quantity.value,unitCost:unitCost.value});await load();}catch(e){error.value=errorMessage(e);}finally{busy.value=false;}}
async function receive(order){busy.value=true;error.value='';try{const line=order.lines[0];await api.post('/purchases/'+order.id+'/receive',{quantity:receiveQuantities.value[order.id]??(line.quantity-line.receivedQuantity)});delete receiveQuantities.value[order.id];await load();}catch(e){error.value=errorMessage(e);}finally{busy.value=false;}}
onMounted(()=>load().catch(e=>error.value=errorMessage(e)));
</script>
<template><section><h1>{{t('purchases.title')}}</h1><p>{{t('purchases.description')}}</p><p v-if="error" role="alert" class="error-message">{{error}}</p><form class="surface-panel form-stack" @submit.prevent="submit"><label>{{t('purchases.supplier')}}<input v-model="supplierName" required maxlength="120"></label><label for="purchases-select-1">{{t('inventory.product_name')}}</label><select id="purchases-select-1" v-model="productId" required><option disabled value="">{{t('common.select')}}</option><option v-for="p in products" :key="p.id" :value="p.id">{{p.sku}} · {{p.name}}</option></select><label>{{t('inventory.quantity')}}<input v-model.number="quantity" type="number" min="0.01" step="0.01" required></label><label>{{t('purchases.cost')}}<input v-model.number="unitCost" type="number" min="0" step="0.01" required></label><pv-button type="submit" :label="t('purchases.create')" :loading="busy"/></form>
<div class="table-scroll surface-panel"><table><thead><tr><th>{{t('purchases.supplier')}}</th><th>{{t('common.state')}}</th><th>{{t('inventory.quantity')}}</th><th>{{t('common.actions')}}</th></tr></thead><tbody><tr v-for="o in orders" :key="o.id"><td>{{o.supplierName}}</td><td>{{t('purchases.'+o.status.toLowerCase())}}</td><td>{{o.lines[0]?.receivedQuantity}} / {{o.lines[0]?.quantity}}</td><td><input v-if="o.status!=='RECEIVED'" type="number" min="0.01" step="0.01" :max="o.lines[0].quantity-o.lines[0].receivedQuantity" :value="receiveQuantities[o.id]??(o.lines[0].quantity-o.lines[0].receivedQuantity)" :aria-label="t('purchases.receiveQuantity')" @input="receiveQuantities[o.id]=Number($event.target.value)" style="width:6rem;margin-right:0.5rem"><pv-button v-if="o.status!=='RECEIVED'" :label="t('purchases.receive')" :disabled="busy" @click="receive(o)"/></td></tr></tbody></table><p v-if="!orders.length">{{t('common.empty')}}</p></div></section></template>
